"""R10b §0.1 item 2: every report table is generated here from the persisted outputs. Writes R10b/tables/*.md and tables/sources.json."""
from __future__ import annotations
import glob, json, os, sys
import numpy as np, pandas as pd
sys.path.insert(0, os.path.join(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))), "phase4", "scripts"))
import phase4_common as P4
RB, C4 = P4.R9.RB, P4.C4; ROOT = P4.ROOT["rehearsal"]; REP = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); TAB = f"{REP}/tables"; os.makedirs(TAB, exist_ok=True); SRC = {}
def emit(name, src, lines): SRC[name] = src; open(f"{TAB}/{name}.md", "w").write(f"<!-- generated by report_tables_r10b.py from {src} -->\n" + "\n".join(lines) + "\n"); print(f"wrote tables/{name}.md")
def f(x, d=3, sign=False):
    if x is None or (isinstance(x, float) and not np.isfinite(x)): return "—"
    if isinstance(x, (int, np.integer)): return f"{x:,}"
    return f"{x:+.{d}f}" if sign else f"{x:.{d}f}"
star = lambda u: f"{u}{' *' if u in RB.SIX else ''}"
# ---- script hashes before / after
before = {l.split()[1].split("/")[-1]: l.split()[0] for l in open(f"{REP}/scripts/sha_before.txt")}; after = {sc: P4.sha256_file(os.path.join(P4.HERE, sc)) for sc in P4.SCRIPTS}
summ = {"phase4_common.py": "rehearsal root → R10b; sealed-row supplement lock (load_supplement: exists, sha256 in the ledger, exactly the five ids, v2.1 columns; merged after the other locks); row_status (refused / no k / ok); dev_min_cells assert; POOL_SEED, DEV_MIN_CELLS, CTRL_TOL, NO_K constants",
        "phase4_build.py": "a row without spacings or paths is refused, a row without k gets status 'not scorable (no k)' and nothing is built; cells_across and thinner_than_development written to pair_stats",
        "phase4_figures.py": "no page and no key entry for a no-k pair (listed under no_page in the key)", "phase4_predict.py": "§A5 environment control on the R10 EW0207 inputs / predictions from OAK before any admitted pair (refuses on failure; comparison in provenance); --control_only; no-k pairs skipped",
        "phase4_score.py": "pooled_row (unit-stratified block bootstrap, seed 20261013); s_lr_W64 removed (asserted absent); cells_across + thinner_than_development per pair; no-k rows reported with their status; pooled statements on the C1 set, C1 + low-amplitude, scorable lockbox; C3 wording"}
emit("script_hashes", "R10b/scripts/sha_before.txt (R10 commit ca0d145) and the committed files", ["| script | sha256 before (R10) | sha256 after (R10b) | change |", "|---|---|---|---|"] + [f"| `{sc}` | `{before[sc][:16]}…` | `{after[sc][:16]}…` | {summ[sc]} |" for sc in P4.SCRIPTS])
# ---- refusal tests
rt = json.load(open("/scratch/users/scdobbs/grl_review/R10b/refusal_tests/refusal_tests.json"))
emit("refusal_tests", "refusal_tests/refusal_tests.json (refusal_tests_r10b.py)", ["| test | result | exception / note |", "|---|---|---|"] + [f"| {t['test']} | {'passed' if t['passed'] else 'FAILED'} | {(t['exception'] or t.get('note') or '—').replace('|', '\\|')[:150]} |" for t in rt["tests"]] + [f"| **total** | {rt['n_passed']} / {rt['n_tests']} passed | node {rt['node']} |"])
# ---- B2 / B4 comparisons
b2 = json.load(open(f"{ROOT}/compare_r10b_B2.json")); L = ["| pair | tile keys / r0 / c0 / s_lr / A_fine identical | F_hr / joint_v1 identical | interior D1 / A_fine_int identical | features: NaN pattern identical, max \\|Δ\\| (≤ 1e-6) | views identical | set-A page pixel-identical (codes) | cells across |", "|---|---|---|---|---|---|---|---|"]
for pid, r in b2["B2"].items(): L.append(f"| {pid} | {r['tile_keys_identical']} / {r['r0_identical']} / {r['c0_identical']} / {r['s_lr_identical']} / {r['A_fine_identical']} | {r['F_hr_identical']} / {r['joint_v1_identical']} | {r['interior_D1_identical']} / {r['A_fine_int_D1_identical']} | {r['features']['nan_pattern_identical']}, {r['features']['max_abs_diff']:.1e} ({r['features']['within_tol']}) | {r['views_identical']} | {r['page_identical']} ({r['codes'][0]} / {r['codes'][1]}) | {r['cells_across']:.2f}{' (thinner)' if r['thinner_than_development'] else ''} |")
L.append(f"| node | {b2['node']} ({b2['cpu']}) | | | | | | |"); emit("build_compare", "rehearsal/compare_r10b_B2.json (compare_r10b.py)", L)
b4 = json.load(open(f"{ROOT}/compare_r10b_B4.json")); L = ["| distance | columns compared | all identical | max \\|Δ\\| over columns | columns dropped (s_lr_W64) | columns added |", "|---|---|---|---|---|---|"]
for tag, b in b4["B4"].items(): L.append(f"| {tag} | {b['n_columns']} | {b['all_identical']} | {max(v for v in b['max_abs_diff_per_column'].values() if np.isfinite(v)):.1e} | {', '.join(b['columns_dropped'])} | {', '.join(b['columns_added'])} |")
emit("score_compare", "rehearsal/compare_r10b_B4.json (compare_r10b.py)", L)
# ---- environment control on two CPU generations
L = ["| job | node | CPU | s_lr identical | GBT_ship max \\|Δ\\| (m) | P-V1 seed-averaged max \\|Δ log₁₀\\| | per seed | passed | seconds |", "|---|---|---|---|---|---|---|---|---|"]
for pf in sorted(glob.glob(f"{ROOT}/provenance/environment_control_*.json")):
    c = json.load(open(pf)); e = c["environment_control"]; L.append(f"| {c.get('slurm_job')} | {e['node'].split('.')[0]} | {e['cpu']} | {e['s_lr_identical']} | {e['gbt_max_abs_diff_m']:.2e} | {e['pv1_seedavg_max_abs_diff_log10']:.2e} | {', '.join(f'{k}: {v:.1e}' for k, v in e['pv1_per_seed_max_abs_diff_log10'].items())} | {e['passed']} | {e.get('seconds', 0):.0f} |")
L.append(f"| tolerances | | | identical | ≤ {P4.CTRL_TOL['gbt_m']:.0e} | ≤ {P4.CTRL_TOL['pv1_log10']:.0e} | | | |"); emit("environment_control", "rehearsal/provenance/environment_control_*.json (phase4_predict.py)", L)
# ---- pooled rows in development (whole pools, triples, cross-table)
tri = json.load(open(f"{ROOT}/triples.json")); L = ["| pool | pairs | whole pool: mean ρ [95 % CI] | lower > 0 | dropped resamples | triples | fraction lower > 0 | pooled mean min / median / max | distinct-unit triples | fraction lower > 0 | min / median / max |", "|---|---|---|---|---|---|---|---|---|---|---|"]
for name, r in tri.items():
    w, t, d = r["whole"], r["triples"], r["triples_distinct_units"]; L.append(f"| {name} | {r['n_pairs']} | {w['mean_rho']:+.3f} [{w['ci95'][0]:+.3f}, {w['ci95'][1]:+.3f}] | {w['lower_gt0']} | {w['n_dropped']} | {t['n']} | {t['frac_lower_gt0']:.3f} | {t['mean_rho_min']:+.2f} / {t['mean_rho_median']:+.2f} / {t['mean_rho_max']:+.2f} | {d['n']} | {f(d['frac_lower_gt0'])} | {f(d['mean_rho_min'], 2, True)} / {f(d['mean_rho_median'], 2, True)} / {f(d['mean_rho_max'], 2, True)} |")
emit("pooled_dev", "rehearsal/triples.json (triples_r10b.py; phase4_score.pooled_row)", L)
L = ["| pool | triple C1 label | lower bound > 0 | lower bound ≤ 0 |", "|---|---|---|---|"]
for name, r in tri.items():
    for lab, c in r["cross_label_vs_lower_gt0"].items(): L.append(f"| {name} | {lab} | {c['lower_gt0']} | {c['lower_le0']} |")
emit("pooled_cross", "rehearsal/triples.json:cross_label_vs_lower_gt0 (triples_r10b.py)", L)
S1 = json.load(open(f"{ROOT}/scores/results_D1.json")); L = ["| role | statement | n units | mean ρ [95 % CI] | lower > 0 | dropped |", "|---|---|---|---|---|---|"]
for role, P in S1["C1_pooled"].items():
    for k, v in P.items():
        if v: L.append(f"| {role} | {k} | {v['n_units']} | {v['mean_rho']:+.3f} [{v['ci95'][0]:+.3f}, {v['ci95'][1]:+.3f}] | {v['lower_gt0']} | {v['n_dropped']} |")
emit("pooled_rehearsal", "rehearsal/scores/results_D1.json:C1_pooled (phase4_score.py)", L)
# ---- cells per window (per pair, from the rehearsal scores) and the W64 recount
pp = pd.read_csv(f"{ROOT}/scores/per_pair_D1.csv"); L = ["| pair | unit | hr_res (m) | lr_native (m) | cells across | thinner than development | view (D1) | ρ s_lr |", "|---|---|---|---|---|---|---|---|"]
for r in pp.sort_values("cells_across").itertuples(): L.append(f"| {r.pair} | {star(r.unit) if r.unit != 'lu16' else 'lu16 (EW0207)'} | {r.hr_res:.2f} | {r.lr_native:.1f} | {r.cells_across:.2f} | {r.thinner_than_development} | {r.view} | {f(r.rho_s_lr, 2, True)} |")
L.append(f"| development minimum (asserted) | {S1['dev_min_cells']:.4f} | | | | | | |"); emit("cells", "rehearsal/scores/per_pair_D1.csv, results_D1.json:dev_min_cells (phase4_score.py)", L)
rr = json.load(open(f"{ROOT}/prereg_v2_final_render.json")) if os.path.exists(f"{ROOT}/prereg_v2_final_render.json") else None
if rr: emit("w64_recount", "R10/rehearsal/scores/per_pair_D1.csv (OAK) via render_prereg_v2_final_r10b.py", ["| item | value |", "|---|---|", f"| pairs of the ten with s_lr_W64 below s_lr at D₁ | {rr['g4']['below']} of 15 (R10 §1 said 14 of 15: right; R10 \"Not pursued\" said 13 of 15: wrong) |", f"| pairs with ship cells ≥ 57 m | {', '.join(rr['g4']['coarse_pairs'])} |", f"| ranges on those pairs | stated in the v2 change note (G4 line) |"])
# ---- ledger of drops
L = ["| stage | item | count | reason |", "|---|---|---|---|", f"| B4 | pairs not scorable at D₁ / 125 m | {int((pp.view == 'not_scorable').sum())} / {int((pd.read_csv(f'{ROOT}/scores/per_pair_D125.csv').view == 'not_scorable').sum())} of 39 | too few tiles or blocks (identical to R10) |",
     f"| B5 | pools | 4 | the ten's C1-set pairs at D₁ ({tri['D1_ten_C1']['n_pairs']}) and 125 m ({tri['D125_ten_C1']['n_pairs']}), each with and without AR26 |", f"| B1 | refusal tests failed | {rt['n_tests'] - rt['n_passed']} of {rt['n_tests']} | — |"]
emit("ledger", "rehearsal scores, triples.json, refusal_tests.json", L); json.dump(SRC, open(f"{TAB}/sources.json", "w"), indent=1); print("wrote tables/sources.json")
